int main() {
    int nums[] = {4, 5, 6, 7, 0, 1, 2};
    int n = 7, target = 0;
    int low = 0, high = n - 1, ans = -1;
    while (low <= high) {
        int mid = (low + high) / 2;
        if (nums[mid] == target) {
            ans = mid;
            break;
        }
        if (nums[low] <= nums[mid]) {
            if (target >= nums[low] && target < nums[mid]) high = mid - 1;
            else low = mid + 1;
        } else {
            if (target > nums[mid] && target <= nums[high]) low = mid + 1;
            else high = mid - 1;
        }
    }
    cout << "Index of " << target << " = " << ans << endl;
}

